mapper.update:
UPDATE catalog_step SET state='READY',round=round+1,attempts=0,fence=fence+1,lease_until=NULL,
    available_at=clock_timestamp(),updated_at=clock_timestamp() WHERE shard_id=#{shard} AND step_key=#{step}
      AND state='PAUSED' AND round=#{round} AND fence=#{fence} AND (lease_until IS NULL OR lease_until<=clock_timestamp())

UPDATE catalog_command SET state='PAUSED',error_type='ATTEMPTS_EXHAUSTED',lease_until=NULL,updated_at=clock_timestamp()
    WHERE shard_id=#{key.shard} AND source_id=#{key.source} AND scope_kind=#{key.scopeKind} AND scope_id=#{key.scopeId} AND command_id=#{key.command}
      AND state='RUNNING' AND round=#{round} AND fence=#{fence} AND attempts=3 AND lease_until<=clock_timestamp()

UPDATE catalog_step SET state='PAUSED',error_type='ATTEMPTS_EXHAUSTED',lease_until=NULL,updated_at=clock_timestamp()
    WHERE shard_id=#{shard} AND step_key=#{step} AND state='RUNNING' AND round=#{round} AND fence=#{fence}
      AND attempts=3 AND lease_until<=clock_timestamp()

UPDATE catalog_command SET state='ADMITTED',round=round+1,attempts=0,fence=fence+1,lease_until=NULL,
    available_at=clock_timestamp(),updated_at=clock_timestamp() WHERE shard_id=#{key.shard} AND source_id=#{key.source}
      AND scope_kind=#{key.scopeKind} AND scope_id=#{key.scopeId} AND command_id=#{key.command}
      AND state='PAUSED' AND round=#{round} AND fence=#{fence} AND (lease_until IS NULL OR lease_until<=clock_timestamp())

UPDATE catalog_command SET state='COMPLETED',phase='COMPLETED',result_bytes=#{result},lease_until=NULL,error_type=NULL,updated_at=clock_timestamp()
    WHERE shard_id=#{key.shard} AND source_id=#{key.source} AND scope_kind=#{key.scopeKind} AND scope_id=#{key.scopeId} AND command_id=#{key.command}
      AND kind='REPLAY_EVENT' AND phase='SEND' AND state IN ('RUNNING','PAUSED','ADMITTED') AND fence=#{fence}
